        {
            var resolvedConcepts = (model.Concepts?.Added ?? new List<Concept>())
                .Concat((model.Concepts?.Updated ?? new List<ConceptDiffUpdate>())
                    .Select(update =>
                    {
                        if (update.Diff is null)
                        {
                            return ((Concept)update.Concept).DeepClone();
